sys_script.script:
(function(current, previous) {
    var val = current.getValue('number');
    if (val && ('' + val).trim() !== '') return;

    var orderRef = current.getValue('production_order');
    var orderNumber = '';

    // Look up the parent Production Order's number
    if (orderRef) {
        var orderGr = new GlideRecord('x_2056099_indust_0_production_order');
        if (orderGr.get(orderRef)) {
            orderNumber = '' + orderGr.getValue('number');
        }
    }

    if (orderNumber) {
        // Generate procurement order number derived from parent: {orderNumber}-PO-{NNN}
        var itemPrefix = orderNumber + '-PO-';

        // Count existing procurement orders for this production order
        var ga = new GlideAggregate('x_2056099_indust_0_proc_order');
        ga.addQuery('production_order', orderRef);
        ga.addAggregate('COUNT');
        ga.query();
        var count = 0;
        if (ga.next()) {
            count = parseInt(ga.getAggregate('COUNT'), 10);
        }

        // Find max existing sequence among procurement orders for this production order
        var gr = new GlideRecord('x_2056099_indust_0_proc_order');
        gr.addQuery('number', 'STARTSWITH', itemPrefix);
        gr.query();
        var maxSeq = 0;
        while (gr.next()) {
            var numVal = '' + gr.getValue('number');
            var parts = numVal.split('-');
            var lastPart = parts[parts.length - 1];
            var num = parseInt(lastPart, 10);
            if (!isNaN(num) && num > maxSeq) {
                maxSeq = num;
            }
        }

        // Start from count+1; fall back to maxSeq+1 if collision
        var nextSeq = count + 1;
        if (nextSeq <= maxSeq) {
            nextSeq = maxSeq + 1;
        }

        var pad = '' + nextSeq;
        while (pad.length < 3) pad = '0' + pad;
        var candidate = itemPrefix + pad;

        // Collision check
        var check = new GlideRecord('x_2056099_indust_0_proc_order');
        check.addQuery('number', candidate);
        check.setLimit(1);
        check.query();
        while (check.hasNext()) {
            check.next();
            nextSeq++;
            pad = '' + nextSeq;
            while (pad.length < 3) pad = '0' + pad;
            candidate = itemPrefix + pad;
            check = new GlideRecord('x_2056099_indust_0_proc_order');
            check.addQuery('number', candidate);
            check.setLimit(1);
            check.query();
        }

        current.setValue('number', candidate);
    } else {
        // Fallback when no parent order: use PO-YYYY-NNN format
        var gen = new AutoNumberGenerator();
        current.setValue('number', gen.generate('x_2056099_indust_0_proc_order', 'number', 'PO', 3, true));
    }
})(current, previous);
